89: // RFC6265 S5.1.1 date parser:
90: function parseDate(str,strict) {
91:   if (!str) return;
92:   var found_time, found_dom, found_month, found_year;
93: 
94:   /* RFC6265 S5.1.1:
95:    * 2. Process each date-token sequentially in the order the date-tokens
96:    * appear in the cookie-date
97:    */
98:   var tokens = str.split(DATE_DELIM);
99:   if (!tokens) return;
100: 
101:   var date = new Date();
102:   date.setMilliseconds(0);
103: 
104:   for (var i=0; i<tokens.length; i++) {
105:     var token = tokens[i].trim();
106:     if (!token.length) continue;
107: 
108:     var result;
109: 
110:     /* 2.1. If the found-time flag is not set and the token matches the time
111:      * production, set the found-time flag and set the hour- value,
112:      * minute-value, and second-value to the numbers denoted by the digits in
113:      * the date-token, respectively.  Skip the remaining sub-steps and continue
114:      * to the next date-token.
115:      */
116:     if (!found_time) {
117:       result = (strict ? STRICT_TIME : TIME).exec(token);
118:       if (result) {
119:         found_time = true;
120:         date.setUTCHours(result[1]);
121:         date.setUTCMinutes(result[2]);
122:         date.setUTCSeconds(result[3]);
123:         continue;
124:       }
125:     }
126: 
127:     /* 2.2. If the found-day-of-month flag is not set and the date-token matches
128:      * the day-of-month production, set the found-day-of- month flag and set
129:      * the day-of-month-value to the number denoted by the date-token.  Skip
130:      * the remaining sub-steps and continue to the next date-token.
131:      */
132:     if (!found_dom) {
133:       result = DAY_OF_MONTH.exec(token);
134:       if (result) {
135:         found_dom = true;
136:         date.setUTCDate(result[1]);
137:         continue;
138:       }
139:     }
140: 
141:     /* 2.3. If the found-month flag is not set and the date-token matches the
142:      * month production, set the found-month flag and set the month-value to
143:      * the month denoted by the date-token.  Skip the remaining sub-steps and
144:      * continue to the next date-token.
145:      */
146:     if (!found_month) {
147:       result = MONTH.exec(token);
148:       if (result) {
149:         found_month = true;
150:         date.setUTCMonth(MONTH_TO_NUM[result[1].toLowerCase()]);
151:         continue;
152:       }
153:     }
154: 
155:     /* 2.4. If the found-year flag is not set and the date-token matches the year
156:      * production, set the found-year flag and set the year-value to the number
157:      * denoted by the date-token.  Skip the remaining sub-steps and continue to
158:      * the next date-token.
159:      */
160:     if (!found_year) {
161:       result = YEAR.exec(token);
162:       if (result) {
163:         var year = result[0];
164:         /* From S5.1.1:
165:          * 3.  If the year-value is greater than or equal to 70 and less
166:          * than or equal to 99, increment the year-value by 1900.
167:          * 4.  If the year-value is greater than or equal to 0 and less
168:          * than or equal to 69, increment the year-value by 2000.
169:          */
170:         if (70 <= year && year <= 99)
171:           year += 1900;
172:         else if (0 <= year && year <= 69)
173:           year += 2000;
174: 
175:         if (year < 1601)
176:           return; // 5. ... the year-value is less than 1601
177: 
178:         found_year = true;
179:         date.setUTCFullYear(year);
180:         continue;
181:       }
182:     }
183:   }
184: 
185:   if (!(found_time && found_dom && found_month && found_year)) {
186:     return; // 5. ... at least one of the found-day-of-month, found-month, found-
187:             // year, or found-time flags is not set,
188:   }
189: 
190:   return date;
191: };
