196:   var m = date.getUTCMinutes(); m = m > 10 ? m : '0'+m;
197:   var s = date.getUTCSeconds(); s = s > 10 ? s : '0'+s;
198:   return NUM_TO_DAY[date.getUTCDay()] + ', ' +
199:     d+' '+ NUM_TO_MONTH[date.getUTCMonth()] +' '+ date.getUTCFullYear() +' '+
200:     h+':'+m+':'+s+' GMT';
201: }
